INSERT INTO summary_item (id, person_id, sort_order, created_at, updated_at, text_en, text_es) VALUES ('sum-001', 'person-001', 1, '2026-11-23T22:55:00.000Z', '2026-11-25T22:47:23.089Z', 'Senior Software Engineer with more than 15 years of experience in software development using technologies such as Visual FoxPro, .NET (C#, VB.NET), JavaScript, Bootstrap, Node.js, React, Angular, MVC, WCF, and .NET Core 3.1/6/8. Strong background in SQL Server (T-SQL and Reporting Services). Experienced in backend development, frontend development, and multi-layer architectures.', 'INGENIERO de Software Senior con más de 15 años de experiencia en desarrollo de software utilizando tecnologías como Visual FoxPro, .NET (C#, VB.NET), JavaScript, Bootstrap, Node.js, React, Angular, MVC, WCF y .NET Core 3.1/6/8. Sólida trayectoria en SQL Server (T-SQL y Reporting Services). Experiencia en desarrollo backend, desarrollo frontend y arquitecturas en múltiples capas.');
INSERT INTO summary_item (id, person_id, sort_order, created_at, updated_at, text_en, text_es) VALUES ('sum-002', 'person-001', 2, '2026-11-23T22:55:00.000Z', '2026-11-23T22:55:00.000Z', 'I have solid experience in the healthcare industry, especially in authorizations, integrations with the Ministry of Health API, automatic request generation, Windows services, and migration of legacy systems. I also have strong knowledge of integral business systems including Billing, Inventory, Accounting, Payroll, Treasury, and Auditing processes.', 'Tengo una sólida experiencia en el sector de la salud, especialmente en autorizaciones, integraciones con la API del Ministerio de Salud, generación automática de solicitudes, servicios de Windows y migración de sistemas heredados. También cuento con un amplio conocimiento de sistemas empresariales integrales, incluidos los procesos de Facturación, Inventario, Contabilidad, Nómina, Tesorería y Auditoría.');
INSERT INTO summary_item (id, person_id, sort_order, created_at, updated_at, text_en, text_es) VALUES ('sum-003', 'person-001', 3, '2026-11-23T22:55:00.000Z', '2026-11-23T22:55:00.000Z', 'I enjoy teamwork, problem solving, and creating software that improves processes and supports business decisions.', 'Disfruto el trabajo en equipo, la resolución de problemas y la creación de software que mejora los procesos y apoya las decisiones de negocio.');
INSERT INTO summary_item (id, person_id, sort_order, created_at, updated_at, text_en, text_es) VALUES ('sum-ffcc350f', 'person-06591b7c', 1, '2026-11-25T00:34:53.336Z', '2026-11-25T00:34:53.336Z', 'Test entry. Water-dwelling yokai with 1,000+ years of experience in river operations, sumo wrestling, and traditional bonesetting medicine.', 'Entrada de prueba. Yokai acuático con más de 1.000 años de experiencia en operaciones fluviales, sumo y medicina tradicional de huesos.');
