INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-001-b01', 'exp-001', 1, 'Backend maintenance and new development in .NET Core (C#) and SQL Server.', 'Mantenimiento backend y nuevo desarrollo en .NET Core (C#) y SQL Server.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-001-b02', 'exp-001', 2, 'Optimization and creation of stored procedures and functions (T-SQL).', 'Optimización y creación de procedimientos almacenados y funciones (T-SQL).');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-001-b03', 'exp-001', 3, 'Development of reports using Reporting Services.', 'Desarrollo de reportes utilizando Reporting Services.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-001-b04', 'exp-001', 4, 'Freelance senior developer supporting US-based projects remotely.', 'Desarrollador senior independiente que apoya de forma remota proyectos con sede en Estados Unidos.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-002-b01', 'exp-002', 1, 'Development of a Health Plans Management System for Ecopetrol using Visual Studio 2015, WCF, and SQL Server.', 'Desarrollo de un Sistema de Gestión de Planes de Salud para Ecopetrol utilizando Visual Studio 2015, WCF y SQL Server.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-002-b02', 'exp-002', 2, 'Development of the "Padres Cotizantes" module for FiduPrevisora using VB.NET, WCF, and SQL Server.', 'Desarrollo del módulo "Padres Cotizantes" para FiduPrevisora utilizando VB.NET, WCF y SQL Server.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-002-b03', 'exp-002', 3, 'Support and development for Affiliation and Certifications modules for Cafesalud and Cruz Blanca.', 'Soporte y desarrollo de los módulos de Afiliación y Certificaciones para Cafesalud y Cruz Blanca.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-002-b04', 'exp-002', 4, 'Complete development and implementation of the MIPRES process for Medimás: Windows services, automatic request generation, authorizations (POS and No POS), reporting to the Ministry, supply management, and Reporting Services.', 'Desarrollo e implementación completa del proceso MIPRES para Medimás: servicios de Windows, generación automática de solicitudes, autorizaciones (POS y No POS), reporte al Ministerio, gestión de suministros y Reporting Services.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-002-b05', 'exp-002', 5, 'Participation in the migration of legacy modules from ASP.NET 2003 to MVC with Razor, Angular, JavaScript, and SQL Server.', 'Participación en la migración de módulos heredados de ASP.NET 2003 a MVC con Razor, Angular, JavaScript y SQL Server.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-003-b01', 'exp-003', 1, 'Development and support of an integral logistics and billing system using Visual FoxPro, SQL Server, C#, and Reporting Services.', 'DESARROLLO y soporte de un sistema integral de logística y facturación utilizando Visual FoxPro, SQL Server, C# y Reporting Services.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-003-b02', 'exp-003', 2, 'System modules included Billing, Demurrage, Container Logistics, Accounting, Fixed Assets, Accounts Payable/Receivable, and Documentation.', 'Los módulos del sistema incluían Facturación, Demurrage, Logística de Contenedores, Contabilidad, Activos Fijos, Cuentas por Pagar/Cobrar y Documentación.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-003-b03', 'exp-003', 3, 'Designed and developed a dynamic interface to migrate modules from Visual FoxPro to .NET (C#) using multi-layer architecture.', 'Diseñé y desarrollé una interfaz dinámica para migrar módulos de Visual FoxPro a .NET (C#) utilizando una arquitectura en múltiples capas.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-004-b01', 'exp-004', 1, 'Implementation and national deployment of the Mobile Medical Auditing System using Palm devices and Visual FoxPro/SQL Server.', 'Implementación y despliegue nacional del Sistema Móvil de Auditoría Médica utilizando dispositivos Palm y Visual FoxPro/SQL Server.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-004-b02', 'exp-004', 2, 'Development, support, and reporting for medical accounts auditing systems for clients in Colombia and Ecuador.', 'Desarrollo, soporte y reportes para sistemas de auditoría de cuentas médicas para clientes en Colombia y Ecuador.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-004-b03', 'exp-004', 3, 'Development of on-site auditing applications using VB.NET, SQL Server, and Crystal Reports.', 'Desarrollo de aplicaciones de auditoría en sitio utilizando VB.NET, SQL Server y Crystal Reports.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-004-b04', 'exp-004', 4, 'Technical support for more than 40 medical auditors.', 'Soporte técnico para más de 40 auditores médicos.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-005-b01', 'exp-005', 1, 'Analysis, design, and development of Payroll, Inventory, and Accounting modules using VB.NET, Crystal Reports, and Firebird.', 'Análisis, diseño y desarrollo de los módulos de Nómina, Inventario y Contabilidad utilizando VB.NET, Crystal Reports y Firebird.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-005-b02', 'exp-005', 2, 'Development of mobile applications for water consumption readings using Windows Mobile (C#).', 'Desarrollo de aplicaciones móviles para lecturas de consumo de agua utilizando Windows Mobile (C#).');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('exp-005-b03', 'exp-005', 3, 'Training and technical support for engineers working on ERP modules.', 'Capacitación y soporte técnico para ingenieros que trabajan en módulos de ERP.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('oexp-001-b01', 'oexp-001', 1, 'Development and modernization of budget and materials management software using Visual FoxPro.', 'Desarrollo y modernización de software de gestión de presupuestos y materiales utilizando Visual FoxPro.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('oexp-001-b02', 'oexp-001', 2, 'System documentation, training, and implementation.', 'Documentación, capacitación e implementación del sistema.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('oexp-002-b01', 'oexp-002', 1, 'Software re-engineering, analysis, documentation, and maintenance in Visual FoxPro and SQL Server.', 'Reingeniería de software, análisis, documentación y mantenimiento en Visual FoxPro y SQL Server.');
INSERT INTO job_highlight (id, job_id, sort_order, text_en, text_es) VALUES ('oexp-003-b01', 'oexp-003', 1, 'Migration of systems from FoxBase to Visual FoxPro and development of ISO 9002 modules.', 'Migración de sistemas de FoxBase a Visual FoxPro y desarrollo de módulos ISO 9002. PURA CARRETA');
